     1|// IVX Diagnostic ErrorBoundary
     2|// Shows the FULL error message + stack trace on the phone screen
     3|// so we can see exactly what crashes without needing logs.
     4|import React, { Component, type ErrorInfo, type ReactNode } from 'react';
     5|import {
