    13|
    14|type ErrorCategory =
    15|  | 'AUTH_ERROR'
    16|  | 'NETWORK_ERROR'
    17|  | 'DATA_ERROR'
    18|  | 'RENDER_ERROR'
    19|  | 'CONFIG_ERROR'
    20|  | 'UNKNOWN_ERROR';
    21|
    22|interface Props {
    23|  children: ReactNode;
    24|}
    25|
    26|interface State {
    27|  hasError: boolean;
    28|  error: Error | null;
    29|  errorInfo: ErrorInfo | null;
    30|  traceId: string | null;
    31|  category: ErrorCategory;
    32|}
    33|
    34|function classifyError(error: Error): ErrorCategory {
    35|  const msg = (error.message || '').toLowerCase();
    36|  if (msg.includes('maximum update depth') || msg.includes('render') || msg.includes('component')) {
    37|    return 'RENDER_ERROR';
    38|  }
    39|  if (msg.includes('auth') || msg.includes('session') || msg.includes('token') || msg.includes('unauthorized')) {
    40|    return 'AUTH_ERROR';
    41|  }
    42|  if (msg.includes('network') || msg.includes('fetch') || msg.includes('timeout') || msg.includes('connection')) {
    43|    return 'NETWORK_ERROR';
    44|  }
    45|  if (msg.includes('supabase url') || msg.includes('config') || msg.includes('api key')) {
    46|    return 'CONFIG_ERROR';
    47|  }
    48|  if (msg.includes('data') || msg.includes('parse') || msg.includes('json')) {
    49|    return 'DATA_ERROR';
    50|  }
    51|  return 'UNKNOWN_ERROR';
    52|}
    53|
    54|function generateTraceId(): string {
    55|  return 'IVX-' + Date.now().toString(36) + '-' + Math.random().toString(36).substring(2, 8);
    56|}
