    62|  RENDER_ERROR: 'IVX encountered a rendering error',
    63|  CONFIG_ERROR: 'Configuration Error',
    64|  UNKNOWN_ERROR: 'Unexpected Error',
    65|};
    66|
    67|export class DiagnosticErrorBoundary extends Component<Props, State> {
